"""EA-MIDST-01 v1.1 draft: the v1.0 seated text (#1758, AXN-0C67, from the title line) transformed in place, at the author's word of
2026-11-11 03:40 ('lets draft it all'). Every edit names the paragraph it replaces or follows; each anchor must occur exactly once.
    python3 apply_v11.py   ->  EA-MIDST-01-v1.1-draft.md"""
import pathlib, re
H = pathlib.Path(__file__).parent
T = (H / "v10-body.md").read_text(encoding="utf-8")

def para(prefix):
    m = [x for x in re.finditer(r"(?m)^" + re.escape(prefix) + r".*$", T)]
    assert len(m) == 1, (prefix, len(m)); return m[0]
def replace_para(prefix, new):
    global T; m = para(prefix); T = T[:m.start()] + new + T[m.end():]
def after_para(prefix, new):
    global T; m = para(prefix); T = T[:m.end()] + "\n\n" + new + T[m.end():]
def sub(old, new, count=1):
    global T; assert T.count(old) == count, (old[:60], T.count(old)); T = T.replace(old, new)

